// Die Dashboard-Seite als ein Stueck Text.
//
// Kein Rahmenwerk, keine Pakete, keine Dateien zum Ausliefern - dasselbe
// Prinzip wie im Rest des Projekts. Die Seite fragt alle fuenf Sekunden
// /api/stand ab und zeichnet neu.

const HTML = String.raw`<!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<title>Ghostxx</title>
<style>
  :root {
    --bg: #060d18; --karte: rgba(12,24,38,.55); --rand: #1b3f5c;
    --text: #dceaf5; --leise: #6f93ad;
    --gut: #35e08a; --warn: #f0b429; --schlecht: #ff5f6d; --akzent: #22d3ee;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0; padding: 16px 16px 66px; color: var(--text);
    font: 14px/1.5 "Segoe UI", system-ui, sans-serif;
    background: var(--bg);
  }

  /* Der Hintergrund: zwei Nebelschleier, die sehr langsam wandern, und ein
     feines Raster darueber. Alles CSS, kein Bild - die Seite bleibt eine
     Datei und laedt nichts nach.
     Fest hinter dem Inhalt, damit beim Scrollen nichts mitwandert. */
  /* Cyan fuehrt, aber nicht allein - ein Hauch vom Violett des Ruhebildschirms
     dahinter, sonst wirkt die Seite tot statt nach denkender KI. Kraeftiger
     als der erste Versuch, der war zu duenn. */
  body::before {
    content: ''; position: fixed; inset: -25%; z-index: -2; pointer-events: none;
    background:
      radial-gradient(closest-side at 50% 26%, rgba(34,211,238,.22), transparent),
      radial-gradient(closest-side at 82% 18%, rgba(139,92,246,.16), transparent),
      radial-gradient(closest-side at 80% 74%, rgba(34,211,238,.14), transparent),
      radial-gradient(closest-side at 12% 78%, rgba(103,232,249,.12), transparent),
      radial-gradient(closest-side at 20% 20%, rgba(56,189,248,.10), transparent);
    filter: blur(30px);
    animation: nebel 46s ease-in-out infinite alternate;
  }
  @keyframes nebel {
    0%   { transform: translate3d(0, 0, 0) scale(1); }
    50%  { transform: translate3d(2.5%, -2%, 0) scale(1.06); }
    100% { transform: translate3d(-2%, 2.5%, 0) scale(1.02); }
  }

  /* Punktraster statt Linien - naeher am HUD-Vorbild, gibt dem Ganzen Tiefe,
     ohne dass man es bewusst sieht. */
  body::after {
    content: ''; position: fixed; inset: 0; z-index: -1; pointer-events: none;
    background-image: radial-gradient(rgba(34,211,238,.5) 1px, transparent 1px);
    background-size: 32px 32px;
    opacity: .09;
    mask-image: radial-gradient(ellipse 90% 70% at 50% 35%, #000 25%, transparent 78%);
    -webkit-mask-image: radial-gradient(ellipse 90% 70% at 50% 35%, #000 25%, transparent 78%);
  }

  /* Wer Bewegung nicht mag oder braucht, bekommt sie nicht - der Regen im
     Ruhebildschirm ist bewusst ausgenommen: Kevins eigener Bildschirm, und
     der Regen ist der ganze Punkt der Szene, siehe .tropfen weiter unten. */
  @media (prefers-reduced-motion: reduce) {
    body::before { animation: none; }
  }

  @keyframes dreh { to { transform: rotate(360deg); } }

  /* ---- Ruhebildschirm ---------------------------------------------------
     Reine Zierde, und das darf sie auch sein: das Dashboard laeuft dahinter
     weiter, hier wird nichts gerechnet. Alles CSS, kein Bild, keine Datei. */
  .ruhe {
    position: fixed; inset: 0; z-index: 50; overflow: hidden; cursor: pointer;
    display: grid; place-items: center;
    background: #171025;
    transition: opacity .9s ease;
  }
  .ruhe.weg { opacity: 0; pointer-events: none; }

  /* Kevins eigenes Waldfoto (ChatGPT) als Grund - kein CSS-Ersatz, ein
     echtes Bild. Alles andere hier drueber ist wieder reines CSS. */
  .buehne { position: absolute; inset: 0; z-index: 0; background-size: cover; background-position: center 38%; }

  /* Dunkler Schleier oben/unten, sonst gehen Uhr und Name im Foto unter. */
  .schleier {
    position: absolute; inset: 0; z-index: 1; pointer-events: none;
    background: linear-gradient(180deg, rgba(10,5,15,.35) 0%, transparent 20%, transparent 72%, rgba(10,5,15,.55) 100%);
  }

  /* Regen: viele duenne Tropfen mit echter Tiefe (nah = groesser, schaerfer,
     heller - fern = kleiner, unschaerfer, blasser). Bewusst OHNE
     Leuchtrand/box-shadow - der liess es wie gezeichnete Striche aussehen
     statt wie echten Regen. */
  .regen { position: absolute; inset: 0; z-index: 2; overflow: hidden; pointer-events: none; }
  .tropfen {
    position: absolute; top: -12%;
    background: linear-gradient(180deg, transparent, rgba(230,230,240,.5) 45%, transparent);
    animation-name: fallen; animation-timing-function: linear; animation-iteration-count: infinite;
  }
  @keyframes fallen {
    from { transform: translate(0, -10vh) rotate(9deg); }
    to   { transform: translate(-8vh, 112vh) rotate(9deg); }
  }

  .ruheinhalt { position: relative; z-index: 3; text-align: center; }

  .ruhename {
    font-size: 46px; font-weight: 300; letter-spacing: .26em;
    color: #f3e9f0; text-shadow: 0 0 22px rgba(255,180,130,.5), 0 2px 14px rgba(0,0,0,.6);
  }
  .ruhestand { margin-top: 12px; color: rgba(243,233,240,.75); font-size: 13px; letter-spacing: .16em; }

  /* Uhrzeit unten - gross, duenn, unaufdringlich. */
  .ruheuhr {
    position: absolute; left: 0; right: 0; bottom: 7%; text-align: center; z-index: 3;
    font-size: 15vh; line-height: 1; font-weight: 100; letter-spacing: .04em;
    color: rgba(255,207,148,.09); font-variant-numeric: tabular-nums;
    pointer-events: none; user-select: none;
  }

  /* Kein Knopf: ein Klick irgendwohin weckt ihn. */
  .ruhe.wacht .ruheinhalt, .ruhe.wacht .ruheuhr { opacity: 0; transition: opacity .5s; }

  /* Der Kern im Dashboard ist der geheime Weg zurueck in den Schlaf. */
  .orb { cursor: pointer; }
  .orb::after {
    content: 'schlafen'; position: absolute; bottom: -18px; left: 50%;
    transform: translateX(-50%); font-size: 10px; letter-spacing: .14em;
    color: var(--leise); opacity: 0; transition: opacity .25s; white-space: nowrap;
  }
  .orb:hover::after { opacity: .8; }

  .hallo {
    position: absolute; opacity: 0; text-align: center; padding: 0 20px;
    font-size: clamp(28px, 6vw, 68px); font-weight: 600; letter-spacing: .1em;
    background: linear-gradient(96deg, #f5d0fe, #a5f3fc, #c4b5fd);
    -webkit-background-clip: text; background-clip: text; color: transparent;
    filter: drop-shadow(0 0 26px rgba(196,181,253,.55));
  }
  .ruhe.wacht .hallo { animation: gruss 2.1s ease forwards; }
  @keyframes gruss {
    0% { opacity: 0; transform: scale(.86); letter-spacing: .3em; }
    28% { opacity: 1; transform: scale(1); letter-spacing: .1em; }
    72% { opacity: 1; }
    100% { opacity: 0; transform: scale(1.04); }
  }

  .frage { border-left: 3px solid var(--akzent); background: #0f1620;
           padding: 10px 12px; border-radius: 8px; margin-bottom: 10px; }
  .frage p { margin: 0 0 4px; }
  .frage .warum { color: var(--leise); font-size: 12px; margin-bottom: 8px; }
  .frage form { display: flex; gap: 6px; }
  .frage input { flex: 1; background: #0b0e13; border: 1px solid var(--rand);
                 color: var(--text); border-radius: 6px; padding: 6px 9px;
                 font: inherit; }
  .frage button { background: var(--akzent); border: 0; color: #08111f;
                  border-radius: 6px; padding: 6px 14px; font: inherit;
                  font-weight: 600; cursor: pointer; }
  .frage.fertig { border-color: var(--gut); opacity: .6; }
  .pause-knopf { background: var(--karte2, #16202c); border: 1px solid var(--rand); color: var(--text);
                 border-radius: 6px; padding: 6px 12px; font: inherit; font-size: 12px;
                 font-weight: 600; cursor: pointer; white-space: nowrap; flex-shrink: 0; }
  .pause-knopf:hover { border-color: var(--akzent); }
  .pause-knopf.aktiv { background: var(--warn); color: #241a04; border-color: var(--warn); }
  /* Neustart-Knopf: bewusst rot/zurueckhaltend, mit eigener Bestaetigung im
     Skript - das hier beendet den echten Prozess, kein Spielzeug. */
  .mini-knopf { background: rgba(255,95,109,.08); border: 1px solid rgba(255,95,109,.4);
                color: var(--schlecht); border-radius: 6px; padding: 4px 10px;
                font: inherit; font-size: 11px; font-weight: 700; letter-spacing: .04em;
                cursor: pointer; white-space: nowrap; }
  .mini-knopf:hover { background: rgba(255,95,109,.18); }
  .mini-knopf:disabled { opacity: .55; cursor: default; }
  /* Neutrale Variante fuer harmlose Knoepfe wie "Terminal" - kein rot, das
     ist Neustart vorbehalten. */
  .mini-knopf.neutral { background: rgba(34,211,238,.08); border-color: rgba(34,211,238,.4); color: var(--akzent); }
  .mini-knopf.neutral:hover { background: rgba(34,211,238,.18); }
  /* Statusleiste unten - echte Messwerte, keine Zierde. */
  .leiste { position: fixed; left: 0; right: 0; bottom: 0; z-index: 5;
            display: flex; gap: 26px; align-items: center; flex-wrap: wrap;
            padding: 10px 20px; background: rgba(6,13,24,.82);
            backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
            border-top: 1px solid rgba(34,211,238,.14);
            font-size: 12px; }
  .mess { display: flex; align-items: center; gap: 8px; }
  .mess b { color: var(--leise); font-weight: 600; letter-spacing: .1em;
            text-transform: uppercase; font-size: 10px; }
  .mess i { font-style: normal; font-variant-numeric: tabular-nums;
            font-family: Consolas, ui-monospace, monospace; color: var(--akzent); }
  .mess.hoch i { color: var(--warn); }
  .mess.sehrhoch i { color: var(--schlecht); }
  .uhr { margin-left: auto; color: var(--leise); font-variant-numeric: tabular-nums;
         font-family: Consolas, ui-monospace, monospace; }
  h1 { font-size: 18px; margin: 0 0 4px; }
  h2 { font-size: 10px; margin: -12px -14px 12px; padding: 11px 14px;
       color: var(--leise); text-transform: uppercase; letter-spacing: .15em;
       font-weight: 600; border-bottom: 1px solid rgba(34,211,238,.14);
       display: flex; align-items: center; justify-content: space-between; gap: 8px; }
  /* Kleine pulsierende Pille an Karten mit wirklich laufendem Datenstrom -
     "LIVE" heisst hier immer: das hier aendert sich gerade wirklich. */
  .live-pill { display: inline-flex; align-items: center; gap: 5px;
               padding: 2px 8px; border: 1px solid rgba(53,224,138,.4);
               background: rgba(53,224,138,.08); color: var(--gut);
               font-size: 9px; letter-spacing: .1em; border-radius: 20px;
               font-weight: 700; text-transform: uppercase; }
  .live-pill i { width: 5px; height: 5px; border-radius: 50%; background: var(--gut);
                 animation: blinken 1.3s ease-in-out infinite; }
  @keyframes blinken { 0%,100% { opacity: 1; } 50% { opacity: .25; } }
  .leise { color: var(--leise); font-size: 12px; }
  /* Drei Spalten, Ghostxx in der Mitte. Auf einem schmalen Bildschirm rutscht
     alles untereinander - der Kern zuerst. */
  .gitter { display: grid; gap: 12px; align-items: start;
            grid-template-columns: minmax(0,1fr) minmax(0,1.05fr) minmax(0,1fr); }
  @media (max-width: 1250px) { .gitter { grid-template-columns: minmax(0,1fr) minmax(0,1fr); } }
  @media (max-width: 820px) { .gitter { grid-template-columns: 1fr; } }
  .spalte { display: grid; gap: 12px; align-content: start; }

  .karte {
    background: var(--karte);
    border: 1px solid rgba(34,211,238,.12); border-radius: 10px; padding: 12px 14px;
    backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
    box-shadow: 0 0 0 1px rgba(34,211,238,.04), 0 16px 34px -22px rgba(0,0,0,.95);
    transition: border-color .3s ease, box-shadow .3s ease;
  }
  .karte:hover {
    border-color: rgba(34,211,238,.32);
    box-shadow: 0 0 0 1px rgba(34,211,238,.1), 0 0 30px -8px rgba(34,211,238,.2),
      0 18px 40px -22px rgba(0,0,0,.95);
  }
  .karte h2 { color: var(--akzent); opacity: .85; }
  .steuergruppe { margin-top: 12px; border-top: 1px solid var(--rand); padding-top: 10px; }
  .steuergruppe:first-child { margin-top: 0; border-top: 0; padding-top: 0; }
  .steuergruppe h3 { margin: 0 0 7px; color: var(--leise); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; }
  .schalter { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 0; background: transparent; border: 0; color: var(--text); text-align: left; cursor: pointer; }
  .schalter:hover { color: #fff; }
  .schalter i { width: 30px; height: 16px; background: #3a2730; border-radius: 12px; position: relative; flex: 0 0 auto; transition: .18s; }
  .schalter i::after { content: ''; width: 12px; height: 12px; background: #f3a2aa; border-radius: 50%; position: absolute; top: 2px; left: 2px; transition: .18s; }
  .schalter.an i { background: #1f5945; } .schalter.an i::after { left: 16px; background: var(--gut); }
  .chatverlauf { min-height: 95px; max-height: 180px; overflow-y: auto; padding: 9px; background: #0b1621; border: 1px solid var(--rand); border-radius: 6px; }
  .chatzeile { margin: 0 0 8px; line-height: 1.45; } .chatzeile:last-child { margin-bottom: 0; }
  .chatzeile b { color: var(--akzent); margin-right: 5px; } .chatzeile.ghost b { color: var(--gut); }
  .chatformular { display: flex; gap: 7px; margin-top: 8px; }
  .chatformular input { min-width: 0; flex: 1; background: #0a111a; color: var(--text); border: 1px solid var(--rand); border-radius: 5px; padding: 8px; }
  .chatformular button { background: var(--akzent); color: #07121b; border: 0; border-radius: 5px; padding: 8px 12px; cursor: pointer; font-weight: 700; }
  .breit { grid-column: 1 / -1; }

  /* Terminal-Overlay statt Dauerkarte im Hauptbild - Kevins Wunsch: Debug-Zeug
     nicht staendig sichtbar, aber einen Klick entfernt. */
  .term-overlay {
    position: fixed; inset: 0; z-index: 60; display: none;
    background: rgba(3,7,14,.72); backdrop-filter: blur(4px);
    place-items: center; padding: 24px;
  }
  .term-overlay.offen { display: grid; }
  .term-box {
    width: min(920px, 100%); max-height: 78vh; display: flex; flex-direction: column;
    background: var(--karte); border: 1px solid rgba(34,211,238,.3); border-radius: 10px;
    padding: 14px 16px; backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
    box-shadow: 0 0 0 1px rgba(34,211,238,.08), 0 24px 60px -20px rgba(0,0,0,.95);
  }
  .term-box .kopf { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
  .term-box .kopf h2 { margin: 0; }
  .term-box .schliessen {
    background: none; border: 1px solid rgba(34,211,238,.3); color: var(--text);
    border-radius: 6px; padding: 4px 10px; cursor: pointer; font-size: 13px;
  }
  .term-box .schliessen:hover { border-color: var(--akzent); color: var(--akzent); }
  .term-box .terminal { max-height: none; flex: 1; }

  /* Der Kern. Reine Zierde - aber er dreht nur, solange Daten kommen. */
  .kern { display: grid; place-items: center; padding: 2px 0 8px; position: relative; }
  /* Duenne, kaum sichtbare Linien vom Kern zu den Karten drumherum - ein
     Hinweis, dass hier alles vom Kern ausgeht. Rein dekorativ, liegt hinter
     allem und reagiert auf nichts. */
  .kern .adern { position: absolute; inset: -14px -40px; pointer-events: none; z-index: 0;
                 opacity: .35; }
  .kern .adern path { fill: none; stroke: var(--akzent); stroke-width: 1;
                       stroke-dasharray: 3 9; animation: aderpuls 5s ease-in-out infinite; }
  .kern .adern path:nth-child(2) { animation-delay: -1.6s; }
  .kern .adern path:nth-child(3) { animation-delay: -3.2s; }
  @keyframes aderpuls { 0%,100% { opacity: .18; } 50% { opacity: .5; } }
  .orb { position: relative; width: 230px; height: 230px; display: grid; place-items: center;
         z-index: 1; animation: kernatmen 4s ease-in-out infinite; }
  @keyframes kernatmen { 0%,100% { transform: scale(1); } 50% { transform: scale(1.025); } }
  /* Weicher Glow-Untergrund, dahinter. */
  .orb::before {
    content: ''; position: absolute; inset: 6%;
    border-radius: 50%; background: radial-gradient(circle, rgba(34,211,238,.32), transparent 70%);
    filter: blur(16px);
  }
  .orb i { position: absolute; border-radius: 50%; }
  /* Aeusserster Ring: duenn, ganz leicht rotierend, kaum Kontrast. */
  .orb i:nth-child(1) {
    inset: 0; border: 1px solid transparent; border-top-color: rgba(34,211,238,.4);
    border-left-color: rgba(34,211,238,.14); animation: dreh 22s linear infinite;
  }
  /* Der eigentliche Kern-Ring: durchgezogen, mit Leuchtrand aussen UND innen -
     das ist der Ring, der das Auge zuerst findet. */
  .orb i:nth-child(2) {
    inset: 42px; border: 2px solid var(--akzent);
    box-shadow: inset 0 0 18px rgba(34,211,238,.5), 0 0 22px rgba(34,211,238,.55);
  }
  /* Gestrichelter Skalenring, dreht sichtbar - der "Instrument"-Anteil. */
  .orb i:nth-child(3) {
    inset: 22px; border: 1px dashed rgba(34,211,238,.5); animation: dreh 16s linear infinite;
  }
  .orb i:nth-child(4) {
    inset: 60px; border: 1px solid transparent; border-top-color: rgba(103,232,249,.55);
    animation: dreh 7s linear infinite reverse;
  }
  .orb b {
    position: relative; display: block; text-align: center;
    font-size: 26px; font-weight: 700; letter-spacing: -.01em;
    color: #e8fbff; text-shadow: 0 0 24px rgba(34,211,238,.75), 0 0 46px rgba(34,211,238,.35);
  }
  /* Kleines Label drueber, Status drunter - beides reine CSS-Beschriftung,
     der Status haengt an denselben Klassen, die das Skript unten schon
     setzt (.denkt / .aus), also ohne jede JS-Aenderung immer korrekt. */
  .orb b::before {
    content: 'SYSTEM CORE'; display: block; font-size: 9px; font-weight: 600;
    letter-spacing: .3em; color: var(--leise); margin-bottom: 6px; text-shadow: none;
  }
  .orb b::after {
    content: 'ONLINE'; display: block; font-size: 9px; font-weight: 700;
    letter-spacing: .15em; color: var(--gut); margin-top: 6px; text-shadow: none;
    font-family: Consolas, ui-monospace, monospace;
  }
  .orb.denkt i:nth-child(1), .orb.denkt i:nth-child(3), .orb.denkt i:nth-child(4) {
    animation-duration: 1.4s;
  }
  .orb.denkt i:nth-child(2) { border-color: var(--gut); box-shadow: inset 0 0 18px rgba(53,224,138,.5), 0 0 22px rgba(53,224,138,.55); }
  .orb.denkt b { text-shadow: 0 0 22px rgba(53,224,138,.7); }
  .orb.denkt b::after { content: 'LIEST GERADE'; color: var(--gut); }
  .orb.aus { animation-play-state: paused; }
  .orb.aus i { animation-play-state: paused; }
  .orb.aus i:nth-child(2) { border-color: var(--schlecht); box-shadow: inset 0 0 18px rgba(255,95,109,.4), 0 0 22px rgba(255,95,109,.4); }
  .orb.aus b::after { content: 'OFFLINE'; color: var(--schlecht); }
  .kernstand { margin-top: 2px; color: var(--leise); font-size: 12px; text-align: center; }
  table { width: 100%; border-collapse: collapse; }
  td { padding: 5px 0; vertical-align: middle; }
  td + td { padding-left: 10px; }
  .zahl { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap;
          font-family: Consolas, ui-monospace, monospace; }
  .marke { display: inline-block; padding: 1px 7px; border-radius: 20px;
           font-size: 11px; border: 1px solid var(--rand); color: var(--leise); }
  .m-angriff, .m-verteidigung { color: #ffb08a; border-color: #6b3520; background: rgba(255,140,80,.08); }
  .m-selbst { color: #c4a2ff; border-color: #4a2f6b; background: rgba(160,110,255,.08); }
  .marke.gut { color: var(--gut); border-color: #1f4d34; background: rgba(53,224,138,.08); }
  .marke.warn { color: var(--warn); border-color: #5a4712; background: rgba(240,180,41,.08); }
  .marke.schlecht { color: var(--schlecht); border-color: #5a1f24; background: rgba(255,95,109,.08); }
  .balken { height: 6px; background: #0a1a28; border-radius: 4px; overflow: hidden; min-width: 70px; }
  .balken i { display: block; height: 100%; background: var(--akzent);
              box-shadow: 0 0 8px rgba(34,211,238,.5); }
  .voll i { background: var(--gut); box-shadow: 0 0 8px rgba(53,224,138,.5); }
  .knapp i { background: var(--warn); box-shadow: 0 0 8px rgba(240,180,41,.5); }
  .warnung { padding: 7px 12px; border-radius: 8px; margin-bottom: 7px;
             border-left: 3px solid var(--warn); background: rgba(240,180,41,.09); }
  .warnung.rot { border-color: var(--schlecht); background: rgba(255,95,109,.10); }
  .fehler { font-family: Consolas, monospace; font-size: 12px; color: #ff9aa4;
            padding: 3px 0; border-bottom: 1px solid var(--rand); }
  .nichts { color: var(--leise); font-style: italic; }
  .punkt { display: inline-block; width: 8px; height: 8px; border-radius: 50%;
           background: var(--gut); margin-right: 6px; }
  .punkt.aus { background: var(--schlecht); }
  .punkt.warn { background: var(--warn); }
  /* Alles in Bildschirmhoehen statt Pixeln.
     Auf 1920x1080 passt so alles auf eine Seite, ohne dass die Seite selbst
     scrollt - lange Listen scrollen INNERHALB ihrer Karte. Auf einem groesseren
     Bildschirm wird von selbst mehr sichtbar. */
  .rollen { max-height: 21vh; overflow-y: auto; }
  #logbuch { max-height: 27vh; overflow-y: auto; }
  #fragen { max-height: 34vh; overflow-y: auto; }
  #bilder { max-height: 30vh; overflow-y: auto; }
  .terminal { max-height: 22vh; overflow-y: auto; margin: 0;
              font: 12px/1.5 Consolas, monospace; color: #7fd4e8;
              white-space: pre-wrap; word-break: break-word; }
  #anmeldungen { max-height: 24vh; overflow-y: auto; }
  ::-webkit-scrollbar { width: 8px; height: 8px; }
  ::-webkit-scrollbar-thumb { background: #1d4460; border-radius: 8px; }
  ::-webkit-scrollbar-track { background: transparent; }
  .tat { padding: 4px 0; border-bottom: 1px solid var(--rand); font-size: 13px; }
  .tat b { font-weight: 600; }
  .tat .wann { color: var(--leise); font-size: 11px; margin-right: 6px;
               font-variant-numeric: tabular-nums; }
  .tat.create b { color: var(--gut); }
  .tat.delete b, .tat.error b { color: var(--schlecht); }
  .tat.update b { color: var(--akzent); }
  .bald { color: var(--akzent); }
  tr.dran td { background: rgba(53,224,138,.10); color: #dff7e9; }
  tr.dran td:first-child { border-left: 2px solid var(--gut); padding-left: 6px; }
  .zeiger { color: var(--gut); animation: pochen 1.6s ease-in-out infinite; }
  @keyframes pochen { 0%,100% { opacity: 1; } 50% { opacity: .35; } }
  .sprung { color: var(--akzent); text-decoration: none;
            border-bottom: 1px dotted rgba(34,211,238,.45); }
  .sprung:hover { color: #7ee7f5; border-bottom-style: solid; }
  /* Was er nicht erkannt hat, soll ins Auge fallen - das ist das, wo jemand
     draufschauen muss. */
  .tat.offen { border-left: 2px solid var(--warn); padding-left: 8px;
               background: rgba(240,180,41,.05); }
</style>
</head>
<body>
  <!-- Ruhebildschirm. Liegt ueber allem, bis jemand ihn wegklickt, und kommt
       nach zehn Minuten ohne Handgriff von selbst zurueck. -->
  <div class="ruhe" id="ruhe">
    <div class="buehne" id="ruhebuehne"></div>
    <div class="schleier"></div>
    <div class="regen" id="regen"></div>
    <div class="ruheuhr" id="ruheuhr"></div>
    <div class="ruheinhalt">
      <div class="ruhename">Ghostxx</div>
      <div class="ruhestand" id="ruhestand">schläft</div>
    </div>
    <div class="hallo" id="hallo">HELLO GHOST MUFFIN</div>
  </div>

  <div id="warnungen"></div>

  <div class="gitter">
    <div class="spalte">
      <div class="karte" id="karte-lauf" style="display:none">
        <h2>Sammelauszahlung</h2>
        <div id="lauf"></div>
      </div>

      <div class="karte">
        <h2>Offene Anmeldungen</h2>
        <div id="anmeldungen"></div>
      </div>

      <div class="karte">
        <h2>Steuerzentrale</h2>
        <div id="steuerung"></div>
      </div>

      <div class="karte">
        <h2>GhostxxCode — Coding-Helfer</h2>
        <div class="chatverlauf" id="chatverlauf"><div class="nichts">Frag ihn was zum Code.</div></div>
        <form class="chatformular" id="chatformular">
          <input id="chattext" maxlength="1200" autocomplete="off" placeholder="Frage zum Code…">
          <button type="submit">Senden</button>
        </form>
      </div>
    </div>

    <div class="spalte">
      <div class="kern">
        <svg class="adern" viewBox="0 0 400 260" preserveAspectRatio="none">
          <path d="M200 130 Q90 70 20 40"></path>
          <path d="M200 130 Q310 70 380 40"></path>
          <path d="M200 130 Q90 190 20 220"></path>
          <path d="M200 130 Q310 190 380 220"></path>
        </svg>
        <div class="orb" id="ring"><i></i><i></i><i></i><i></i><b>Ghostxx</b></div>
        <div class="kernstand">
          <div id="technik">…</div>
          <div id="laufzeit"></div>
          <div id="stand">lädt…</div>
        </div>
      </div>

      <div class="karte">
        <h2><span>Was er in Discord tut</span><span class="live-pill"><i></i>Live</span></h2>
        <div id="aktivitaet" class="rollen"></div>
      </div>

      <div class="karte">
        <h2>Logbuch — wartet auf Auszahlung</h2>
        <div id="logbuch"></div>
      </div>
    </div>

    <div class="spalte">
      <div class="karte" id="karte-fragen" style="display:none">
        <h2>Er fragt</h2>
        <div id="fragen"></div>
      </div>

      <div class="karte">
        <h2><span>Bilder — was er gelesen hat</span><span class="live-pill"><i></i>OCR</span></h2>
        <div id="bilder"></div>
      </div>

      <div class="karte">
        <h2>Letzte Fehler</h2>
        <div id="fehler"></div>
      </div>

      <div class="karte">
        <h2>Selbstverbesserung</h2>
        <div id="selbstverbesserung"></div>
      </div>
    </div>
  </div>

  <div class="leiste" id="leiste"></div>

  <!-- Terminal-Overlay: nur sichtbar, wenn jemand den Knopf in der Leiste
       anklickt. Der Inhalt wird trotzdem staendig mitaktualisiert, damit er
       beim Oeffnen sofort aktuell ist. -->
  <div class="term-overlay" id="term-overlay">
    <div class="term-box">
      <div class="kopf">
        <h2>Terminal</h2>
        <button class="schliessen" id="term-schliessen">Schließen ✕</button>
      </div>
      <pre id="terminal" class="terminal"></pre>
    </div>
  </div>

<script>
const $ = (id) => document.getElementById(id);

// Kevins eigenes Waldfoto fuer den Ruhebildschirm - als Daten-URI, damit
// die Seite weiterhin eine einzige Datei bleibt und nichts nachlaedt.
const WALDFOTO = 'data:image/webp;base64,';
const sicher = (t) => String(t == null ? '' : t).replace(/[<>&]/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]));

function dauer(sek) {
  if (sek == null) return '';
  const m = Math.round(sek / 60);
  if (m < 1) return 'unter 1 Min';
  if (m < 60) return m + ' Min';
  return Math.floor(m / 60) + ' Std ' + (m % 60) + ' Min';
}

function balken(anteil, klasse) {
  const p = Math.min(100, Math.round(anteil * 100));
  return '<div class="balken ' + klasse + '"><i style="width:' + p + '%"></i></div>';
}

/** Kleine Kurve aus den letzten Messwerten. */
function kurve(werte, farbe) {
  if (!werte || werte.length < 2) return '<svg width="56" height="18"></svg>';
  const breite = 56;
  const hoehe = 18;
  const schritt = breite / (werte.length - 1);
  const punkte = werte.map((w, i) =>
    (i * schritt).toFixed(1) + ',' + (hoehe - (Math.min(100, Math.max(0, w)) / 100) * hoehe).toFixed(1)
  ).join(' ');
  return '<svg width="' + breite + '" height="' + hoehe + '" viewBox="0 0 ' + breite + ' ' + hoehe + '">'
    + '<polyline points="' + punkte + '" fill="none" stroke="' + farbe + '" stroke-width="1.5"'
    + ' stroke-linejoin="round" stroke-linecap="round" opacity="0.9"/></svg>';
}

function messKlasse(prozent) {
  if (prozent === null || prozent === undefined) return '';
  if (prozent >= 90) return 'sehrhoch';
  if (prozent >= 70) return 'hoch';
  return '';
}

function messwert(name, wert, prozent, verlaufWerte, farbe) {
  return '<div class="mess ' + messKlasse(prozent) + '">'
    + '<b>' + name + '</b><i>' + wert + '</i>'
    + (verlaufWerte ? kurve(verlaufWerte, farbe) : '') + '</div>';
}

function zeichneLeiste(s) {
  if (!s) return '';
  const teile = [];

  teile.push(messwert('CPU', (s.cpu === null ? '—' : s.cpu + ' %'), s.cpu, s.verlauf.cpu, '#58a6ff'));
  teile.push(messwert('RAM', s.ramBelegtGb + ' / ' + s.ramGesamtGb + ' GB',
    Math.round(s.ramBelegtGb / s.ramGesamtGb * 100), s.verlauf.ram, '#3fb950'));

  if (s.gpu) {
    teile.push(messwert('GPU', s.gpu.last + ' % · ' + s.gpu.grad + '°', s.gpu.last, s.verlauf.gpu, '#d29922'));
    teile.push(messwert('VRAM', (s.gpu.vramMb / 1024).toFixed(1) + ' / ' + Math.round(s.gpu.vramGesamtMb / 1024) + ' GB',
      Math.round(s.gpu.vramMb / s.gpu.vramGesamtMb * 100), s.verlauf.vram, '#f778ba'));
  }

  if (s.disk) {
    teile.push(messwert('Platte', s.disk.belegtGb + ' / ' + s.disk.gesamtGb + ' GB',
      Math.round(s.disk.belegtGb / s.disk.gesamtGb * 100)));
  }

  if (s.pingMs !== null) {
    teile.push(messwert('Discord', s.pingMs + ' ms', s.pingMs > 500 ? 95 : (s.pingMs > 150 ? 75 : 10)));
  }

  teile.push('<button id="term-knopf" class="mini-knopf neutral" title="Terminal-Log anzeigen">▤ Terminal</button>');
  teile.push('<button id="neustart-knopf" class="mini-knopf" title="Bot manuell neustarten - dauert ca. 15-20 Sekunden">↻ Neustart</button>');
  teile.push('<button id="aus-knopf" class="mini-knopf" title="Bot komplett ausschalten - Watchdog und Windows-Autostart warten dann, bis er wieder eingeschaltet wird">⏻ Ausschalten</button>');
  teile.push('<div class="uhr">' + new Date().toLocaleTimeString('de-DE') + '</div>');
  return teile.join('');
}

function zeichneBilder(d) {
  const b = d.bilder;
  // Jede Zahl genau einmal, und dazu was er GERADE tut. Vorher standen hier
  // drei verschiedene Zaehler fuer "gelesen", die nie uebereinstimmten.
  const zustandFarbe = b.zustand && b.zustand.was === 'liest' ? 'var(--gut)'
    : (b.zustand && (b.zustand.was === 'spiel' || b.zustand.was === 'speicher' || b.zustand.was === 'pausiert') ? 'var(--warn)' : 'var(--leise)');

  // Der BESTAND: was wirklich in den Tickets liegt. Das ist die Zahl, von der
  // alle anderen Teilmengen sind - Kevins Rechnung ging vorher nicht auf, weil
  // hier die Chronik stand und daneben der Merkzettel.
  const s = b.bestand;
  const teil = (n, text, farbe) => (n
    ? ' · <b style="color:' + farbe + '">' + n + '</b> ' + text
    : '');

  const bestand = s
    ? '<div style="margin-bottom:8px">'
      + '<b style="font-size:15px">' + s.beitraege + '</b> unbezahlte Nachweise in '
      + '<b>' + s.mitBildern + '</b> von <b>' + s.tickets + '</b> Tickets'
      + '<div class="leise" style="margin-top:2px">davon '
      + '<b style="color:var(--gut)">' + s.gelesen + '</b> ausgewertet'
      + teil(s.ohneEvent, 'ohne Event', 'var(--warn)')
      + teil(s.unlesbar, 'nicht lesbar', 'var(--schlecht)')
      + teil(s.wartend, 'in der Schlange', 'var(--text)')
      + teil(s.offen, 'noch nicht angesehen', 'var(--leise)')
      + '</div>'
      // Haeufen sich die Unlesbaren in einem Ticket, ist das kein Zufall.
      + (s.unlesbarJeTicket && s.unlesbarJeTicket.length === 1 && s.unlesbar > 2
        ? '<div class="leise" style="margin-top:2px;color:var(--warn)">alle '
          + s.unlesbar + ' unlesbaren liegen in <b>' + sicher(s.unlesbarJeTicket[0].name)
          + '</b></div>'
        : '')
      + '</div>'
    : '';

  // Kevins eigener Knopf: nur das Bildlesen haelt an, Chat und Events nicht -
  // fuers Zocken ohne dass die Karte geteilt werden muss. Der Text auf dem
  // Knopf sagt immer, was ein Klick als naechstes TUT, nicht was gerade ist -
  // sonst muesste man erst nachdenken, was "Bildlesen: an" eigentlich bedeutet.
  const pauseKnopf = '<button id="bilder-pause-knopf" class="pause-knopf' + (b.pausiert ? ' aktiv' : '') + '" '
    + 'data-pausiert="' + (b.pausiert ? '1' : '0') + '">'
    + (b.pausiert ? '▶ Bildlesen fortsetzen' : '⏸ Bildlesen pausieren')
    + '</button>';

  // Die CHRONIK: alles, was er je geoeffnet hat. Waechst ewig weiter und ist
  // deshalb groesser als der Bestand - das ist kein Fehler, muss aber
  // drangeschrieben stehen.
  const kopf = '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px">'
    + '<div style="flex:1">' + bestand + '</div>' + pauseKnopf + '</div>'
    + '<div class="leise" style="margin-bottom:8px">'
    + 'insgesamt gelesen, seit es ihn gibt: <b>' + b.gelesen + '</b>'
    + (b.gescheitert ? ' · <b style="color:var(--schlecht)">' + b.gescheitert + '</b> nicht lesbar' : '')
    + (b.zustand ? '<br><span style="color:' + zustandFarbe + '">' + sicher(b.zustand.text) + '</span>' : '')
    + (b.sucht && b.wartend ? '<br><span class="leise">sucht weiter ab <b>' + sicher(b.sucht) + '</b></span>' : '')
    + (b.unterbrochen ? '<br><span style="color:var(--warn)">war unterbrochen, macht dort weiter</span>' : '')
    + (b.pausiert ? '<br><span style="color:var(--warn)">Bildlesen pausiert - Chat und Events laufen normal weiter</span>' : '')
    + '</div>';

  if (!b.liste.length) {
    return kopf + '<div class="nichts">Noch nichts gelesen. Neue Bilder werden automatisch ausgewertet.</div>';
  }

  const zeilen = b.liste.map((g) => {
    // Drei verschiedene Zustaende, und sie duerfen NICHT gleich aussehen:
    // erkannt, gelesen-aber-nichts-drauf, und gar nicht gelesen. Beim ersten
    // Lauf sah ein fehlgeschlagener Aufruf aus wie "nichts erkannt" - das
    // Bild waere nie wieder angesehen worden.
    const garnicht = !g.antwort;
    const nichts = !garnicht && !(g.labels || []).length && !g.antwort.wappen;
    const erkannt = (g.labels || []).length
      ? '<b style="color:var(--gut)">' + sicher(g.labels.join(', ')) + '</b>'
      : (g.antwort && g.antwort.wappen
        ? '<b style="color:var(--gut)">SK (Wappen)</b>'
        : (garnicht
          ? '<b style="color:var(--schlecht)">konnte nicht gelesen werden</b>'
          : '<b style="color:var(--warn)">kein Event drauf</b>'
            // Eine Fehlanzeige gilt erst beim zweiten Mal. Solange steht dabei,
            // dass er nochmal hinschaut - sonst sieht es aus wie ein Urteil.
            + ((g.leerVersuche || 0) < 2
              ? ' <span class="leise">— schaut nochmal</span>'
              : ' <span class="leise">— zweimal geprüft</span>')));

    // Was jemand behauptet hat, gegen das, was wirklich im Bild steht.
    const angegeben = g.angegeben ? sicher(g.angegeben.slice(0, 34)) : '(kein Text)';

    // Sprung direkt zur Nachricht. Gerade bei "nichts erkannt" ist das der
    // ganze Punkt: sonst weiss man nicht, welches Bild gemeint ist.
    const ziel = g.kanalId && g.messageId
      ? 'https://discord.com/channels/' + d.guildId + '/' + g.kanalId + '/' + g.messageId
      : '';
    const link = ziel
      ? '<a class="sprung" href="' + ziel + '" target="_blank" rel="noreferrer">„' + angegeben + '"</a>'
      : '„' + angegeben + '"';

    return '<div class="tat' + (nichts || garnicht ? ' offen' : '') + '">'
      + '<span class="wann">' + new Date(g.gelesenAm).toLocaleTimeString('de-DE') + '</span>'
      + erkannt
      + (g.zeitpunkt ? ' <span class="leise">' + sicher(g.zeitpunkt.text) + '</span>' : '')
      + '<div class="leise">' + (g.werName ? sicher(g.werName) + ' — ' : '')
      + 'angegeben: ' + link + '</div>'
      + '</div>';
  });

  return kopf + zeilen.join('');
}

function zeichneAnmeldungen(liste) {
  if (!liste.length) return '<div class="nichts">Gerade ist nichts offen.</div>';

  return '<table>' + liste.map((a) => {
    const klasse = a.dabei >= a.max && a.max ? 'voll'
      : (a.schliesstIn !== null && a.schliesstIn <= 6 && a.anteil >= 0.6 ? 'knapp' : '');
    const markeKlasse = a.art === 'Selbst erstellt' ? 'm-selbst'
      : (a.art === 'Geplant' ? '' : 'm-angriff');
    const schliesst = a.schliesstIn === null
      ? (a.offenSeitStunden > 48 ? 'seit ' + Math.round(a.offenSeitStunden / 24) + ' Tagen offen' : 'offen')
      : (a.schliesstIn <= 0 ? 'schließt gleich' : 'noch ' + a.schliesstIn + ' Min');

    return '<tr>'
      + '<td><span class="marke ' + markeKlasse + '">' + sicher(a.art) + '</span></td>'
      + '<td><b>' + sicher(a.titel) + '</b>'
        + (a.gegner ? ' <span class="leise">' + sicher(a.gegner) + '</span>' : '') + '</td>'
      + '<td style="width:110px">' + balken(a.anteil, klasse) + '</td>'
      + '<td class="zahl">' + a.dabei + '/' + (a.max || '?')
        + (a.ersatz ? ' <span class="leise">+' + a.ersatz + '</span>' : '') + '</td>'
      + '<td class="zahl leise">' + schliesst + '</td>'
      + '</tr>';
  }).join('') + '</table>';
}

function zeichneLauf(l) {
  if (!l || !l.seit) return '';
  const anteil = l.gesamt ? l.fertig / l.gesamt : 0;
  return '<div style="margin-bottom:8px"><b>' + (l.laeuft ? 'Läuft' : 'Fertig') + '</b> — '
    + l.fertig + '/' + l.gesamt + ' Tickets</div>'
    + balken(anteil, l.laeuft ? '' : 'voll')
    + '<div class="leise" style="margin-top:8px">'
    + l.bilder + ' Bilder geprüft · ' + l.zugestellt + ' Abrechnungen raus · '
    + l.abgehakt + ' abgehakt · ' + dauer(l.dauerSek)
    + (l.restSek != null ? ' · noch etwa ' + dauer(l.restSek) : '') + '</div>'
    + (l.aktuell ? '<div class="leise">gerade: ' + sicher(l.aktuell) + '</div>' : '');
}

function zeichneSelbstverbesserung(sv) {
  if (!sv) return '<div class="nichts">Wird noch gezählt…</div>';

  const kopf = '<div class="leise" style="margin-bottom:7px">' + sv.heutigeLaeufe + ' / 5 heute</div>';
  if (!sv.letzteEintraege.length) return kopf + '<div class="nichts">Noch nichts gemeldet.</div>';

  // Dieselben drei Ampelfarben wie ueberall im Dashboard: offen = gelb,
  // abgelehnt/ignoriert = rot, alles andere (z.B. umgesetzt) = gruen.
  const farbe = (status) => (
    status === 'offen' ? 'warn' : (status === 'abgelehnt' || status === 'ignoriert' ? 'schlecht' : 'gut')
  );

  const zeilen = sv.letzteEintraege.map((e) => '<div class="tat' + (e.entscheidung === 'offen' ? ' offen' : '') + '">'
    + '<span class="wann">' + (e.erkanntAm ? new Date(e.erkanntAm).toLocaleTimeString('de-DE') : '') + '</span>'
    + '<b>' + sicher(e.titel) + '</b>'
    + ' <span class="marke ' + farbe(e.entscheidung) + '">' + sicher(e.entscheidung) + '</span>'
    + '</div>');

  return kopf + zeilen.join('');
}

function zeichneLogbuch(lb, d) {
  if (!lb) return '<div class="nichts">Wird noch gezählt…</div>';
  if (!lb.zeilen.length) return '<div class="nichts">Nichts offen — alles abgerechnet.</div>';

  // Bewusst anders benannt als im Bilder-Feld: DAS hier sind Nachweise, die
  // noch nicht abgerechnet sind. Ob er sie schon gelesen hat, ist eine andere
  // Frage - vorher hiess beides "Bilder" und sah aus wie ein Widerspruch.
  const kopf = '<div class="leise" style="margin-bottom:8px">'
    + lb.bilder + ' unbezahlte Nachweise in ' + lb.mitOffenen + ' von ' + lb.tickets + ' Tickets</div>';

  // Ein Zeiger auf die Zeile, an der er gerade arbeitet. Die Liste steht
  // alphabetisch, genau wie er sie abarbeitet - so sieht man sofort, wo er ist
  // und was noch kommt.
  const laeuftAn = d && d.bilder ? d.bilder.aktuellKanal : '';

  return kopf + '<table>' + lb.zeilen.slice(0, 14).map((z) => {
    const dran = laeuftAn && z.kanalId === laeuftAn;
    return '<tr' + (dran ? ' class="dran"' : '') + '>'
      + '<td>' + (dran ? '<span class="zeiger">▶</span> ' : '') + sicher(z.name) + '</td>'
      + '<td class="zahl">' + z.offen + '</td></tr>';
  }).join('') + '</table>'
  + (lb.zeilen.length > 14 ? '<div class="leise">… und ' + (lb.zeilen.length - 14) + ' weitere</div>' : '');
}

// Beantwortete Fragen bleiben stehen, bis die Seite neu geladen wird - sonst
// verschwindet die Zeile unter den Fingern, sobald man abschickt.
const erledigt = new Set();

function zeichneFragen(fragen) {
  const offen = (fragen || []).filter((f) => !erledigt.has(f.id));
  $('karte-fragen').style.display = offen.length ? '' : 'none';
  if (!offen.length) return;

  // Nicht neu zeichnen, solange jemand tippt - sonst ist der Text weg.
  if (document.activeElement && document.activeElement.tagName === 'INPUT') return;

  $('fragen').innerHTML = offen.map((f) =>
    '<div class="frage" data-id="' + sicher(f.id) + '">'
    + '<p>' + sicher(f.frage) + '</p>'
    + '<div class="warum">' + sicher(f.warum) + '</div>'
    + '<form><input placeholder="Antwort…" autocomplete="off">'
    + '<button type="submit">Merken</button></form></div>'
  ).join('');

  for (const kasten of document.querySelectorAll('.frage')) {
    kasten.querySelector('form').addEventListener('submit', async (e) => {
      e.preventDefault();
      const feld = kasten.querySelector('input');
      const antwort = feld.value.trim();
      if (!antwort) return;

      const frage = kasten.querySelector('p').textContent;
      feld.disabled = true;

      const r = await fetch('/api/antwort', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ frage, antwort, id: kasten.dataset.id }),
      }).then((x) => x.json()).catch(() => ({ ok: false }));

      if (r.ok) {
        erledigt.add(kasten.dataset.id);
        kasten.classList.add('fertig');
        kasten.querySelector('form').innerHTML = '<span class="leise">Gemerkt.</span>';
      } else {
        feld.disabled = false;
        kasten.querySelector('.warum').textContent = 'Hat nicht geklappt: ' + (r.reason || 'unbekannt');
      }
    });
  }
}

const SCHALTER_GRUPPEN = [
  ['Event & Chat', [['eventScheduler', 'Event-Scheduler'], ['terminErinnerungen', 'Termin-Erinnerungen'], ['chat', 'Ghostxx-Chat'], ['commands', 'Alle Commands']]],
  ['Bilder', [['visaBilder', 'Reisepässe prüfen'], ['chatBilder', 'Bilder im Chat lesen']]],
  ['Logbuch', [['logbuchSortieren', 'Tickets sortieren']]],
  ['Selbstverbesserung', [['selbstverbesserung', 'Selbst verbessern']]],
  ['Discord-Logs', [['auditLog', 'Audit-Log'], ['logNachrichten', 'Nachrichten'], ['logMitglieder', 'Mitglieder & Rollen'], ['logSprache', 'Sprachkanäle'], ['logSelbststumm', 'Mikro & Kopfhörer'], ['logKanaele', 'Kanäle'], ['botLog', 'Bot-Meldungen'], ['fehlerLog', 'Fehler-Meldungen']]],
];

function zeichneSteuerung(schalter) {
  $('steuerung').innerHTML = SCHALTER_GRUPPEN.map(([titel, werte]) =>
    '<div class="steuergruppe"><h3>' + titel + '</h3>' + werte.map(([key, text]) =>
      '<button class="schalter ' + (schalter[key] !== false ? 'an' : '') + '" data-key="' + key + '" data-an="' + (schalter[key] !== false ? '1' : '0') + '"><span>' + text + '</span><i></i></button>'
    ).join('') + '</div>'
  ).join('');

  for (const knopf of document.querySelectorAll('.schalter')) {
    knopf.addEventListener('click', async () => {
      knopf.disabled = true;
      await fetch('/api/schalter', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key: knopf.dataset.key, an: knopf.dataset.an !== '1' }),
      }).catch(() => null);
      laden();
    });
  }
}

const dashboardChat = [];
function zeichneDashboardChat() {
  $('chatverlauf').innerHTML = dashboardChat.length
    ? dashboardChat.map((z) => '<div class="chatzeile ' + z.rolle + '"><b>' + (z.rolle === 'ghost' ? 'Ghostxx' : 'Du') + '</b>' + sicher(z.text) + '</div>').join('')
    : '<div class="nichts">Frag ihn was zum Code.</div>';
  $('chatverlauf').scrollTop = $('chatverlauf').scrollHeight;
}

$('chatformular').addEventListener('submit', async (e) => {
  e.preventDefault();
  const feld = $('chattext');
  const text = feld.value.trim();
  if (!text) return;
  dashboardChat.push({ rolle: 'du', text });
  feld.value = ''; feld.disabled = true;
  zeichneDashboardChat();
  const antwort = await fetch('/api/chat', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text }),
  }).then((r) => r.json()).catch(() => ({ ok: false, text: 'Keine Verbindung zu Ghostxx.' }));
  dashboardChat.push({ rolle: 'ghost', text: antwort.text || 'Das hat gerade nicht geklappt.' });
  feld.disabled = false; feld.focus();
  zeichneDashboardChat();
});

async function laden() {
  let d;
  try {
    d = await (await fetch('/api/stand')).json();
  } catch {
    $('stand').textContent = 'keine Verbindung zum Bot';
    // Der Ring steht still und wird rot, wenn nichts mehr kommt. So sieht man
    // von der anderen Seite des Zimmers, dass der Bot weg ist.
    $('ring').classList.add('aus');
    return;
  }
  $('ring').classList.remove('aus');
  $('ring').classList.toggle('denkt', Boolean(d.rechnet));

  // Auch im Schlaf steht dran, was er tut - dann sieht man vom Sofa aus, ob
  // er noch Bilder liest.
  $('ruhestand').textContent = d.rechnet
    ? 'liest gerade ein Bild'
    : (d.bilder && d.bilder.wartend
      ? d.bilder.wartend + ' Bilder in der Schlange'
      : 'alles erledigt');

  zeichneFragen(d.fragen);
  $('stand').textContent = 'Stand ' + new Date(d.zeit).toLocaleTimeString('de-DE');
  $('laufzeit').textContent = 'läuft seit ' + d.system.laufzeit;
  $('leiste').innerHTML = zeichneLeiste(d.system);
  $('bilder').innerHTML = zeichneBilder(d);

  // innerHTML baut den Knopf bei jedem Aufruf neu - deshalb hier jedes Mal
  // frisch binden, genau wie beim Neustart-Knopf gleich darunter.
  const termKnopf = document.getElementById('term-knopf');
  if (termKnopf) {
    termKnopf.addEventListener('click', () => $('term-overlay').classList.add('offen'));
  }

  // innerHTML baut den Knopf bei jedem Aufruf neu - deshalb hier jedes Mal
  // frisch binden, genau wie beim Bildlesen-Pause-Knopf unten.
  const neustartKnopf = document.getElementById('neustart-knopf');
  if (neustartKnopf) {
    neustartKnopf.addEventListener('click', async () => {
      if (!confirm('Bot wirklich neustarten? Dauert ca. 15-20 Sekunden, in denen nichts reagiert.')) return;
      neustartKnopf.disabled = true;
      neustartKnopf.textContent = 'startet neu…';
      await fetch('/api/neustart', { method: 'POST' }).catch(() => null);
    });
  }

  // Deutlich groessere Warnung als beim Neustart: das legt den ganzen Bot
  // still, nicht nur den Prozess neu. Wieder an geht nur ueber genau diese
  // Seite (siehe run-bot.ps1), solange der Bot aus ist, also zweimal fragen.
  const ausKnopf = document.getElementById('aus-knopf');
  if (ausKnopf) {
    ausKnopf.addEventListener('click', async () => {
      if (!confirm('Ghostxx WIRKLICH ausschalten? Er reagiert dann auf gar nichts mehr - '
        + 'kein Chat, keine Events, keine Erinnerungen, keine automatische Schliessung von Anmeldungen. '
        + 'Windows-Autostart und der Watchdog warten, bis du ihn ueber diese Seite wieder einschaltest.')) return;
      if (!confirm('Ganz sicher? Das ist kein Neustart - er bleibt aus, bis du ihn selbst wieder anmachst.')) return;
      ausKnopf.disabled = true;
      ausKnopf.textContent = 'schaltet aus…';
      await fetch('/api/aus', { method: 'POST' }).catch(() => null);
    });
  }

  // innerHTML baut den Knopf bei jedem Aufruf neu - deshalb hier jedes Mal
  // frisch binden, genau wie bei den Fragen oben. Kein alter Knopf, an dem
  // ein Klick ins Leere liefe.
  const pauseKnopf = document.getElementById('bilder-pause-knopf');
  if (pauseKnopf) {
    pauseKnopf.addEventListener('click', async () => {
      const jetztPausiert = pauseKnopf.dataset.pausiert === '1';
      pauseKnopf.disabled = true;
      await fetch('/api/bilder-pause', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ an: !jetztPausiert }),
      }).catch(() => null);
      laden();
    });
  }

  const t = d.technik;
  const punkt = !t.erreichbar ? 'aus' : (t.knapp ? 'warn' : '');
  $('technik').innerHTML = '<span class="punkt ' + punkt + '"></span>'
    + (t.erreichbar
      ? (t.modelle.length ? t.modelle.map((m) => sicher(m.name) + ' (' + m.vramGb + ' GB)').join(', ') : 'Ollama bereit, nichts geladen')
        + (t.freiMb != null ? ' · ' + Math.round(t.freiMb / 1024) + ' GB frei' : '')
      : 'Ollama antwortet nicht');

  $('warnungen').innerHTML = d.warnungen.map((w) =>
    '<div class="warnung ' + (w.stufe === 'rot' ? 'rot' : '') + '">' + sicher(w.text) + '</div>'
  ).join('');

  const lauf = zeichneLauf(d.lauf);
  $('karte-lauf').style.display = lauf ? '' : 'none';
  $('lauf').innerHTML = lauf;

  $('anmeldungen').innerHTML = zeichneAnmeldungen(d.anmeldungen);
  $('logbuch').innerHTML = zeichneLogbuch(d.logbuch, d);
  zeichneSteuerung(d.schalter || {});

  $('aktivitaet').innerHTML = d.aktivitaet.length
    ? d.aktivitaet.slice(0, 25).map((a) =>
      '<div class="tat ' + sicher(a.farbe) + '">'
      + '<span class="wann">' + new Date(a.zeit).toLocaleTimeString('de-DE') + '</span>'
      + '<b>' + sicher(a.titel) + '</b>'
      + (a.text ? ' <span class="leise">' + sicher(a.text) + '</span>' : '')
      + '</div>').join('')
    : '<div class="nichts">Seit dem Start nichts passiert.</div>';

  $('terminal').textContent = d.terminal.length
    ? d.terminal.join('\n')
    : '(keine Logdatei gefunden)';

  $('fehler').innerHTML = d.fehler.length
    ? d.fehler.slice(0, 8).map((f) =>
      '<div class="fehler">' + new Date(f.zeit).toLocaleTimeString('de-DE') + ' — '
      + sicher(f.titel) + ': ' + sicher(f.grund) + '</div>').join('')
    : '<div class="nichts">Keine Fehler.</div>';

  $('selbstverbesserung').innerHTML = zeichneSelbstverbesserung(d.selbstverbesserung);
}

// ---- Ruhebildschirm --------------------------------------------------------
//
// Regen einmal streuen und dann nur noch von CSS fallen lassen - kein
// Zeitgeber, keine Schleife. Die Seite soll auch nach acht Stunden nicht
// warm werden.
//
// Tiefenschaerfe per Zufall statt echtem 3D: nahe Tropfen sind groesser,
// heller und schaerfer, ferne kleiner, blasser und leicht unscharf - das
// reicht, damit der Regen wie echte Tiefe wirkt statt wie eine flache Ebene.
(function regenStreuen() {
  $('ruhebuehne').style.backgroundImage = 'url(' + WALDFOTO + ')';

  let html = '';
  for (let i = 0; i < 420; i += 1) {
    const links = (Math.random() * 116 - 8).toFixed(2);
    const tiefe = Math.random();
    const hoehe = 20 + tiefe * 55;
    const breite = (0.5 + tiefe * 1.0).toFixed(2);
    const deckkraft = (0.22 + tiefe * 0.32).toFixed(2);
    const unschaerfe = (1 - tiefe) * 0.8;
    const dauer = (0.42 + Math.random() * 0.5).toFixed(2);
    const verzoegerung = (Math.random() * 2).toFixed(2);
    html += '<div class="tropfen" style="left:' + links + '%;height:' + hoehe + 'px;width:' + breite + 'px;'
      + 'opacity:' + deckkraft + ';filter:blur(' + unschaerfe.toFixed(1) + 'px);'
      + 'animation-duration:' + dauer + 's;animation-delay:-' + verzoegerung + 's"></div>';
  }
  $('regen').innerHTML = html;
})();

// Die Uhr im Ruhebildschirm. Einmal pro Minute - der Rest ist CSS.
(function ruheUhr() {
  const stellen = () => {
    const jetzt = new Date();
    $('ruheuhr').textContent = String(jetzt.getHours()).padStart(2, '0')
      + ':' + String(jetzt.getMinutes()).padStart(2, '0');
  };
  stellen();
  setInterval(stellen, 30 * 1000);
})();

let ruhezeit = null;

function schlafen() {
  const r = $('ruhe');
  r.classList.remove('weg', 'wacht');
}

function aufwachen() {
  const r = $('ruhe');
  if (r.classList.contains('wacht')) return;

  // Erst der Gruss, dann geht der Vorhang auf.
  r.classList.add('wacht');
  setTimeout(() => r.classList.add('weg'), 1900);
}

// Ein Klick irgendwohin auf den Ruhebildschirm weckt ihn - kein Knopf.
$('ruhe').addEventListener('click', aufwachen);

// Und der Kern im Dashboard schickt ihn wieder schlafen. Nirgends
// angeschrieben ausser einem leisen Hinweis beim Draufzeigen.
$('ring').addEventListener('click', schlafen);

// Terminal-Overlay schliessen: per Knopf, per Klick daneben, per Escape.
// Statisches HTML, deshalb einmalig binden statt bei jedem laden().
$('term-schliessen').addEventListener('click', () => $('term-overlay').classList.remove('offen'));
$('term-overlay').addEventListener('click', (e) => {
  if (e.target.id === 'term-overlay') $('term-overlay').classList.remove('offen');
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') $('term-overlay').classList.remove('offen');
});

// Nach zehn Minuten ohne Handgriff schlaeft er wieder ein. Sonst brennt sich
// das Dashboard nachts in den Bildschirm.
function ruheAufschieben() {
  clearTimeout(ruhezeit);
  ruhezeit = setTimeout(schlafen, 10 * 60 * 1000);
}

for (const was of ['mousemove', 'keydown', 'click', 'wheel']) {
  document.addEventListener(was, () => {
    if ($('ruhe').classList.contains('weg')) ruheAufschieben();
  }, { passive: true });
}

laden();
setInterval(laden, 5000);
</script>
</body>
</html>`;

function seite() {
  return HTML;
}

module.exports = { seite };
